using System.Globalization;
using System.Text;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;

namespace LibreWPF.Xaml.FSharp;

// The C# object graph of the XAML generator, printed as F#. F# has no partial classes: the x:Class type is a class of its own that inherits the root
// element's type, declares the x:Name fields, and builds the tree in a constructor. Event handlers are looked up by name on the run-time type of the
// object (a subclass written in F# defines them), because the generated file comes before the code that has them.
internal sealed class FSharpPrinter
{
    private static readonly HashSet<string> s_keywords = new(StringComparer.Ordinal)
    {
        "abstract", "and", "as", "assert", "base", "begin", "class", "default", "delegate", "do", "done", "downcast", "downto", "elif", "else", "end",
        "exception", "extern", "false", "finally", "fixed", "for", "fun", "function", "global", "if", "in", "inherit", "inline", "interface", "internal",
        "lazy", "let", "match", "member", "module", "mutable", "namespace", "new", "not", "null", "of", "open", "or", "override", "private", "public",
        "rec", "return", "sig", "static", "struct", "then", "to", "true", "try", "type", "upcast", "use", "val", "void", "when", "while", "with", "yield",
        "atomic", "break", "checked", "component", "const", "constraint", "constructor", "continue", "event", "external", "include", "mixin", "parallel",
        "process", "protected", "pure", "sealed", "tailcall", "trait", "virtual",
    };

    private readonly StringBuilder _out = new();
    private readonly bool _bootstrap;
    private readonly HashSet<string> _fields = new(StringComparer.Ordinal);
    private int _indent;

    private FSharpPrinter(bool bootstrap) => _bootstrap = bootstrap;

    // bootstrap: the project has the SDK's F# bootstrap (an executable): each generated class starts the platform before it builds its tree.
    public static bool TryPrint(string csharp, out string fsharp, out string error, bool bootstrap = false)
    {
        var tree = CSharpSyntaxTree.ParseText(csharp, new CSharpParseOptions(preprocessorSymbols: Array.Empty<string>()));
        try
        {
            fsharp = new FSharpPrinter(bootstrap).Print((CompilationUnitSyntax)tree.GetRoot());
            error = string.Empty;
            return true;
        }
        catch (NotSupportedException ex)
        {
            fsharp = string.Empty;
            error = ex.Message;
            return false;
        }
    }

    private string Print(CompilationUnitSyntax unit)
    {
        _out.AppendLine("// <auto-generated by LibreWPF.Xaml.FSharp.Tool />");
        foreach (var member in unit.Members)
        {
            Member(member);
        }

        return _out.ToString();
    }

    private void Line(string text) => _out.Append(' ', _indent * 4).AppendLine(text);

    private void Member(MemberDeclarationSyntax member)
    {
        switch (member)
        {
            case BaseNamespaceDeclarationSyntax ns:
                Line("namespace " + Type(ns.Name));
                CollectRegistrations(ns);
                _indent++;
                foreach (var inner in ns.Members)
                {
                    Member(inner);
                }
                _indent--;
                break;
            case ClassDeclarationSyntax cls when cls.Identifier.Text.StartsWith("__XsgComponent_", StringComparison.Ordinal):
                break; // its registration is read by CollectRegistrations and printed as an attribute of the class
            case ClassDeclarationSyntax cls:
                Class(cls);
                break;
            default:
                throw new NotSupportedException($"the member {member.Kind()} has no F# form");
        }
    }

    // A module initializer has no F# form: the registrations it makes (component by resource path, dictionary by resource path) become an attribute of the
    // class, and XsgSupport.registerComponents makes them when the first generated class is constructed.
    private readonly Dictionary<string, (string Assembly, string Path, bool Dictionary, bool Component)> _registrations = new(StringComparer.Ordinal);

    private void CollectRegistrations(BaseNamespaceDeclarationSyntax ns)
    {
        foreach (var cls in ns.Members.OfType<ClassDeclarationSyntax>())
        {
            var path = cls.Members.OfType<FieldDeclarationSyntax>()
                .Where(f => f.Modifiers.Any(m => m.IsKind(SyntaxKind.ConstKeyword)))
                .SelectMany(f => f.Declaration.Variables).FirstOrDefault(v => v.Identifier.Text == "ResourcePath")?.Initializer?.Value as LiteralExpressionSyntax;
            foreach (var call in cls.DescendantNodes().OfType<InvocationExpressionSyntax>())
            {
                var method = call.Expression is MemberAccessExpressionSyntax access ? access.Name.Identifier.Text : string.Empty;
                if (method is not ("RegisterComponent" or "RegisterDictionary") || call.ArgumentList.Arguments.Count != 3
                    || call.ArgumentList.Arguments[2].Expression.DescendantNodesAndSelf().OfType<ObjectCreationExpressionSyntax>().FirstOrDefault() is not { } created)
                {
                    continue;
                }

                var assembly = call.ArgumentList.Arguments[0].Expression is LiteralExpressionSyntax a0 ? a0.Token.ValueText : string.Empty;
                var resource = call.ArgumentList.Arguments[1].Expression is LiteralExpressionSyntax a1 ? a1.Token.ValueText : path?.Token.ValueText;
                if (resource is null)
                {
                    throw new NotSupportedException($"{method} of {created.Type}: the resource path is not a literal");
                }

                var target = created.Type.ToString();
                target = target[(target.LastIndexOf('.') + 1)..];
                _registrations.TryGetValue(target, out var previous);
                _registrations[target] = (assembly, resource, previous.Dictionary || method == "RegisterDictionary", previous.Component || method == "RegisterComponent");
            }
        }
    }

    // Helpers of the generated C# that exist once, in XsgSupport (XsgSupport.g.fs), instead of in every class.
    private static readonly Dictionary<string, string> s_supportFunctions = new(StringComparer.Ordinal)
    {
        ["__XsgApplyExtension"] = "LibreWPF.Xaml.Generated.XsgSupport.applyExtension",
        ["__XsgProvideValue"] = "LibreWPF.Xaml.Generated.XsgSupport.provideValue",
        ["__XsgLoadDictionary"] = "LibreWPF.Xaml.Generated.XsgSupport.loadDictionary",
    };

    private static readonly HashSet<string> s_supportMembers = new(StringComparer.Ordinal)
    {
        "__XsgApplyExtension", "__XsgProvideValue", "__XsgLoadDictionary", "__XsgExtensionServiceProvider", "__XsgCompiledProperty", "__XsgRegister",
    };

    private readonly HashSet<string> _methods = new(StringComparer.Ordinal);
    private readonly HashSet<string> _letFields = new(StringComparer.Ordinal);

    private void Class(ClassDeclarationSyntax cls)
    {
        foreach (var field in cls.Members.OfType<FieldDeclarationSyntax>())
        {
            if (field.Modifiers.Any(m => m.IsKind(SyntaxKind.ConstKeyword)))
            {
                continue;
            }

            foreach (var variable in field.Declaration.Variables)
            {
                (variable.Initializer is null ? _fields : _letFields).Add(variable.Identifier.Text);
            }
        }

        foreach (var method in cls.Members.OfType<MethodDeclarationSyntax>())
        {
            _methods.Add(method.Identifier.Text);
        }

        var access = cls.Modifiers.Any(m => m.IsKind(SyntaxKind.InternalKeyword)) ? "internal " : string.Empty;
        var baseType = cls.BaseList is { Types.Count: > 0 } list ? Type(list.Types[0].Type) : "obj";
        if (_registrations.TryGetValue(cls.Identifier.Text, out var registration))
        {
            Line($"[<LibreWPF.Xaml.Generated.XsgComponent(\"{registration.Assembly}\", \"{registration.Path}\", {(registration.Dictionary ? "true" : "false")}, {(registration.Component ? "true" : "false")})>]");
        }

        Line("[<AllowNullLiteral>]");
        Line($"type {access}{Name(cls.Identifier.Text)}() as this =");
        _indent++;
        Line($"inherit {baseType}()");

        // let bindings (fields with an initializer) come before the do bindings and the members
        foreach (var field in cls.Members.OfType<FieldDeclarationSyntax>())
        {
            if (field.Modifiers.Any(m => m.IsKind(SyntaxKind.ConstKeyword)))
            {
                continue;
            }

            foreach (var variable in field.Declaration.Variables.Where(v => v.Initializer is not null))
            {
                Line($"let {Name(variable.Identifier.Text)} = {Expression(variable.Initializer!.Value)}");
            }
        }

        if (_bootstrap)
        {
            Line("do ProGpu.Wpf.Sdk.PortableBootstrap.ensure ()");
        }

        if (_registrations.ContainsKey(cls.Identifier.Text))
        {
            Line($"do LibreWPF.Xaml.Generated.XsgSupport.registerComponents (typeof<{Name(cls.Identifier.Text)}>.Assembly)");
        }

        Line("do this.InitializeComponent()");
        foreach (var member in cls.Members)
        {
            switch (member)
            {
                case FieldDeclarationSyntax field when field.Modifiers.Any(m => m.IsKind(SyntaxKind.ConstKeyword)):
                    break;
                case FieldDeclarationSyntax field:
                    foreach (var variable in field.Declaration.Variables.Where(v => v.Initializer is null))
                    {
                        var fieldAccess = field.Modifiers.Any(m => m.IsKind(SyntaxKind.InternalKeyword)) ? "internal " : field.Modifiers.Any(m => m.IsKind(SyntaxKind.PrivateKeyword)) ? "private " : string.Empty;
                        Line($"[<DefaultValue>] val mutable {fieldAccess}{Name(variable.Identifier.Text)} : {Type(field.Declaration.Type)}");
                    }
                    break;
                case ConstructorDeclarationSyntax { Body.Statements: [ExpressionStatementSyntax { Expression: InvocationExpressionSyntax { Expression: IdentifierNameSyntax { Identifier.Text: "InitializeComponent" } } }] }:
                    break; // the constructor above already calls it
                case MethodDeclarationSyntax method when s_supportMembers.Contains(method.Identifier.Text):
                    break;
                case ClassDeclarationSyntax nested when s_supportMembers.Contains(nested.Identifier.Text):
                    break;
                case MethodDeclarationSyntax { Identifier.Text: "InitializeComponent" } method:
                    Line("member this.InitializeComponent() : unit =");
                    _indent++;
                    foreach (var statement in method.Body!.Statements)
                    {
                        Statement(statement);
                    }
                    Line("()");
                    _indent--;
                    break;
                case MethodDeclarationSyntax { Identifier.Text: "FindResource" } method when method.ParameterList.Parameters.Count == 1:
                    PrintDictionaryFindResource();
                    break;
                case MethodDeclarationSyntax { ParameterList.Parameters.Count: 0, Body: not null } method when method.ReturnType is PredefinedTypeSyntax { Keyword.Text: "object" }:
                    PrintObjectMethod(method);
                    break;
                default:
                    throw new NotSupportedException($"the helper member {member.Kind()} {(member as MethodDeclarationSyntax)?.Identifier.Text ?? (member as BaseTypeDeclarationSyntax)?.Identifier.Text} of the generated class has no F# form");
            }
        }

        Line("member private this.__wireEvent(target: obj, eventName: string, handler: string) : unit =");
        Line("    let flags = System.Reflection.BindingFlags.Instance ||| System.Reflection.BindingFlags.Public ||| System.Reflection.BindingFlags.NonPublic");
        Line("    let ev = target.GetType().GetEvent(eventName)");
        Line("    let mi = this.GetType().GetMethod(handler, flags)");
        Line("    if isNull ev then raise (System.MissingMemberException(target.GetType().FullName, eventName))");
        Line("    if isNull mi then raise (System.MissingMethodException(this.GetType().FullName, handler))");
        Line("    ev.AddEventHandler(target, System.Delegate.CreateDelegate(ev.EventHandlerType, this, mi))");
        _indent--;
    }

    // `object __Create_1() { var x = ...; return x; }`: the entries of a lazily built dictionary.
    private void PrintObjectMethod(MethodDeclarationSyntax method)
    {
        Line($"member private this.{Name(method.Identifier.Text)}() : obj =");
        _indent++;
        var statements = method.Body!.Statements;
        for (var i = 0; i < statements.Count; i++)
        {
            if (statements[i] is ReturnStatementSyntax { Expression: { } returned })
            {
                if (i != statements.Count - 1)
                {
                    throw new NotSupportedException("a return that is not the last statement");
                }

                Line($"box ({Expression(returned)})");
                _indent--;
                return;
            }

            Statement(statements[i]);
        }

        throw new NotSupportedException($"the method {method.Identifier.Text} does not end with return");
    }

    // The StaticResource lookup of a generated loose dictionary (the C# member FindResource): the scopes being built, then the dictionary, then the application.
    private void PrintDictionaryFindResource()
    {
        foreach (var text in new[]
        {
            "member private this.FindResource(key: obj) : obj =",
            "    let mutable found : obj = null",
            "    let mutable i = __scopes.Count - 1",
            "    while isNull found && i >= 0 do",
            "        if __scopes.[i].Contains(key) then found <- System.Windows.Markup.XamlSourceGeneratedResources.ResolveEntry(__scopes.[i].[key], this)",
            "        i <- i - 1",
            "    if not (isNull found) then found",
            "    elif this.Contains(key) && not (System.Windows.Markup.XamlSourceGeneratedResources.IsEntryBeingCreated(this, key)) then",
            "        System.Windows.Markup.XamlSourceGeneratedResources.ResolveEntry(this.[key], this)",
            "    else",
            "        let app = if isNull System.Windows.Application.Current then null else System.Windows.Application.Current.TryFindResource(key)",
            "        if isNull app then raise (System.Windows.ResourceReferenceKeyNotFoundException(\"Cannot find resource named '\" + string key + \"'.\", key)) else app",
        })
        {
            Line(text);
        }
    }

    private void Statement(StatementSyntax statement)
    {
        switch (statement)
        {
            case LocalDeclarationStatementSyntax local:
                foreach (var variable in local.Declaration.Variables)
                {
                    var init = variable.Initializer is null ? "Unchecked.defaultof<_>" : Expression(variable.Initializer.Value);
                    if (local.Declaration.Type.IsVar)
                    {
                        Line($"let {Name(variable.Identifier.Text)} = {init}");
                    }
                    else
                    {
                        Line($"let mutable {Name(variable.Identifier.Text)} : {Type(local.Declaration.Type)} = {init}");
                    }
                }
                break;
            case ExpressionStatementSyntax { Expression: AssignmentExpressionSyntax assignment }:
                Assignment(assignment);
                break;
            case ExpressionStatementSyntax { Expression: InvocationExpressionSyntax call }:
                Line(Expression(call) + " |> ignore");
                break;
            case ExpressionStatementSyntax { Expression: ConditionalAccessExpressionSyntax access }:
                Line($"if not (isNull ({Expression(access.Expression)})) then {Expression(access.Expression)}{Binding(access.WhenNotNull)} |> ignore");
                break;
            case IfStatementSyntax { Else: null } ifStatement:
                Line($"if {Expression(ifStatement.Condition)} then");
                _indent++;
                if (ifStatement.Statement is BlockSyntax block)
                {
                    foreach (var inner in block.Statements)
                    {
                        Statement(inner);
                    }
                }
                else
                {
                    Statement(ifStatement.Statement);
                }
                Line("()");
                _indent--;
                break;
            default:
                throw new NotSupportedException($"the statement {statement.Kind()} ({Short(statement)}) has no F# form");
        }
    }

    private void Assignment(AssignmentExpressionSyntax assignment)
    {
        var left = assignment.Left;
        switch (assignment.Kind())
        {
            case SyntaxKind.SimpleAssignmentExpression:
                Line($"{Target(left)} <- {Expression(assignment.Right)}");
                break;
            case SyntaxKind.AddAssignmentExpression or SyntaxKind.SubtractAssignmentExpression when left is IdentifierNameSyntax identifier:
            {
                var variable = Name(identifier.Identifier.Text);
                var combine = assignment.IsKind(SyntaxKind.AddAssignmentExpression) ? "Combine" : "Remove";
                var delegateValue = assignment.Right is ParenthesizedLambdaExpressionSyntax ? $"System.Action{Expression(assignment.Right)}" : Expression(assignment.Right);
                Line($"{variable} <- System.Delegate.{combine}({variable}, {delegateValue}) :?> System.Action");
                break;
            }
            case SyntaxKind.SubtractAssignmentExpression when left is MemberAccessExpressionSyntax && assignment.Right is MemberAccessExpressionSyntax { Expression: ThisExpressionSyntax }:
                break; // `x.Event -= this.Handler` before the += (Hot Reload idempotence): the handler is wired once, in the constructor; any other -= fails below
            case SyntaxKind.AddAssignmentExpression when left is MemberAccessExpressionSyntax member && assignment.Right is MemberAccessExpressionSyntax { Expression: ThisExpressionSyntax } handler:
                Line($"this.__wireEvent({Expression(member.Expression)}, \"{member.Name.Identifier.Text}\", \"{handler.Name.Identifier.Text}\")");
                break;
            default:
                throw new NotSupportedException($"the assignment {Short(assignment)} has no F# form");
        }
    }

    // The left side of an assignment: element access is written a.[k].
    private string Target(ExpressionSyntax left) => left is ElementAccessExpressionSyntax element
        ? $"{Expression(element.Expression)}.[{Arguments(element.ArgumentList)}]"
        : Expression(left);

    private string Expression(ExpressionSyntax expression)
    {
        switch (expression)
        {
            case LiteralExpressionSyntax literal:
                return Literal(literal);
            case ThisExpressionSyntax:
                return "this";
            case IdentifierNameSyntax { Identifier.Text: "__XsgCompiledProperty" }:
                return "LibreWPF.Xaml.Generated.XsgCompiledProperty";
            case IdentifierNameSyntax identifier:
                // a field of the class is reached through `this` in F#
                return _fields.Contains(identifier.Identifier.Text) ? "this." + Name(identifier.Identifier.Text) : Name(identifier.Identifier.Text);
            case PredefinedTypeSyntax or AliasQualifiedNameSyntax or QualifiedNameSyntax or GenericNameSyntax:
                return Type(expression);
            case MemberAccessExpressionSyntax member:
                return Expression(member.Expression) + "." + Name(member.Name.Identifier.Text) + GenericArguments(member.Name);
            case InvocationExpressionSyntax { Expression: IdentifierNameSyntax { Identifier.Text: "__XsgProvideValue" } } call when call.ArgumentList.Arguments.Count == 3:
                return $"LibreWPF.Xaml.Generated.XsgSupport.provideValueFor({Arguments(call.ArgumentList)})";
            case InvocationExpressionSyntax { Expression: IdentifierNameSyntax { Identifier.Text: var helper } } call when s_supportFunctions.ContainsKey(helper):
                return $"{s_supportFunctions[helper]}({Arguments(call.ArgumentList)})";
            case InvocationExpressionSyntax call when IsByteColorFactory(call):
                return $"{Expression(call.Expression)}({string.Join(", ", call.ArgumentList.Arguments.Select(a => "(byte (" + Argument(a.Expression) + "))"))})";
            case InvocationExpressionSyntax call:
                return $"{Expression(call.Expression)}({Arguments(call.ArgumentList)})";
            case ElementAccessExpressionSyntax element:
                return $"{Expression(element.Expression)}.[{Arguments(element.ArgumentList)}]";
            case ObjectCreationExpressionSyntax creation:
                return Creation(creation);
            case CastExpressionSyntax cast:
                // ISupportInitialize is only ever cast to from a type known to implement it (the generator checks): a safe upcast, which F# will not take as a downcast.
                return cast.Type is PredefinedTypeSyntax { Keyword.Text: "object" }
                    ? $"(box {Expression(cast.Expression)})"
                    : Type(cast.Type) == "System.ComponentModel.ISupportInitialize" || Type(cast.Type) == "global.System.ComponentModel.ISupportInitialize"
                    ? $"({Expression(cast.Expression)} :> {Type(cast.Type)})"
                    : $"({Expression(cast.Expression)} :?> {Type(cast.Type)})";
            case BinaryExpressionSyntax { RawKind: (int)SyntaxKind.AsExpression } asExpression:
                return $"({Expression(asExpression.Left)} :?> {Type((TypeSyntax)asExpression.Right)})";
            case TypeOfExpressionSyntax typeOf:
                return $"typeof<{Type(typeOf.Type)}>";
            case ParenthesizedExpressionSyntax parenthesized:
                return "(" + Expression(parenthesized.Expression) + ")";
            case PostfixUnaryExpressionSyntax { RawKind: (int)SyntaxKind.SuppressNullableWarningExpression } suppressed:
                return Expression(suppressed.Operand);
            case PrefixUnaryExpressionSyntax prefix:
                return prefix.Kind() switch
                {
                    SyntaxKind.LogicalNotExpression => "(not " + Expression(prefix.Operand) + ")",
                    SyntaxKind.UnaryMinusExpression => "(-" + Expression(prefix.Operand) + ")",
                    _ => throw new NotSupportedException($"the operator {prefix.OperatorToken.Text} has no F# form"),
                };
            case BinaryExpressionSyntax binary:
                return Binary(binary);
            case ConditionalExpressionSyntax conditional:
                return $"(if {Expression(conditional.Condition)} then {Expression(conditional.WhenTrue)} else {Expression(conditional.WhenFalse)})";
            case ParenthesizedLambdaExpressionSyntax lambda:
                return Lambda(lambda.ParameterList.Parameters.Select(p => Name(p.Identifier.Text)), lambda.Body);
            case SimpleLambdaExpressionSyntax simple:
                return Lambda(new[] { Name(simple.Parameter.Identifier.Text) }, simple.Body);
            case DefaultExpressionSyntax:
                return "Unchecked.defaultof<_>";
            default:
                throw new NotSupportedException($"the expression {expression.Kind()} ({Short(expression)}) has no F# form");
        }
    }

    // `() => a.b = c`, `o => o.X`, `(o, v) => o.X = v`: an F# lambda; the delegate type comes from the place it is passed to (a method argument).
    // An object creation is upcast to what the delegate returns (`static () => new T()` for a Func<DependencyObject>).
    private string Lambda(IEnumerable<string> parameters, CSharpSyntaxNode body)
    {
        var names = string.Join(" ", parameters);
        var head = names.Length == 0 ? "fun ()" : "fun " + names;
        return body switch
        {
            AssignmentExpressionSyntax assignment when assignment.IsKind(SyntaxKind.SimpleAssignmentExpression)
                => $"({head} -> {Target(assignment.Left)} <- {Expression(assignment.Right)})",
            ObjectCreationExpressionSyntax creation => $"({head} -> ({Creation(creation)} :> _))",
            ExpressionSyntax value => $"({head} -> {Expression(value)})",
            _ => throw new NotSupportedException("a lambda with a block body has no F# form here"),
        };
    }

    private string Binding(ExpressionSyntax whenNotNull) => whenNotNull switch
    {
        MemberBindingExpressionSyntax member => "." + Name(member.Name.Identifier.Text),
        InvocationExpressionSyntax { Expression: MemberBindingExpressionSyntax member } call => "." + Name(member.Name.Identifier.Text) + "(" + Arguments(call.ArgumentList) + ")",
        _ => throw new NotSupportedException($"the conditional access {whenNotNull.Kind()}"),
    };

    private string Binary(BinaryExpressionSyntax binary)
    {
        var left = Expression(binary.Left);
        var right = Expression(binary.Right);
        var isNull = binary.Right.IsKind(SyntaxKind.NullLiteralExpression);
        return binary.Kind() switch
        {
            SyntaxKind.EqualsExpression => isNull ? $"(isNull ({left}))" : $"({left} = {right})",
            SyntaxKind.NotEqualsExpression => isNull ? $"(not (isNull ({left})))" : $"({left} <> {right})",
            SyntaxKind.LogicalAndExpression => $"({left} && {right})",
            SyntaxKind.LogicalOrExpression => $"({left} || {right})",
            SyntaxKind.AddExpression => $"({left} + {right})",
            SyntaxKind.SubtractExpression => $"({left} - {right})",
            SyntaxKind.MultiplyExpression => $"({left} * {right})",
            SyntaxKind.DivideExpression => $"({left} / {right})",
            SyntaxKind.BitwiseOrExpression => $"({left} ||| {right})",
            SyntaxKind.BitwiseAndExpression => $"({left} &&& {right})",
            _ => throw new NotSupportedException($"the operator {binary.OperatorToken.Text} has no F# form"),
        };
    }

    // new T(a, b) { P = v }  ->  T(a, b, P = v)
    private string Creation(ObjectCreationExpressionSyntax creation)
    {
        var arguments = creation.ArgumentList is null ? new List<string>() : creation.ArgumentList.Arguments.Select(a => Argument(a.Expression)).ToList();
        if (creation.Initializer is { } initializer)
        {
            if (initializer.IsKind(SyntaxKind.CollectionInitializerExpression))
            {
                throw new NotSupportedException("a collection initializer has no F# form here");
            }

            foreach (var entry in initializer.Expressions)
            {
                if (entry is not AssignmentExpressionSyntax { Left: IdentifierNameSyntax name } assignment)
                {
                    throw new NotSupportedException("an object initializer entry that is not an assignment");
                }

                arguments.Add($"{Name(name.Identifier.Text)} = {Expression(assignment.Right)}");
            }
        }

        return $"{Type(creation.Type)}({string.Join(", ", arguments)})";
    }

    // Color.FromArgb/FromRgb take bytes; the generated C# writes integer literals, which F# will not implicitly narrow.
    private static bool IsByteColorFactory(InvocationExpressionSyntax call) =>
        call.Expression is MemberAccessExpressionSyntax { Name.Identifier.Text: "FromArgb" or "FromRgb" } member
        && member.Expression.ToString().EndsWith("System.Windows.Media.Color", StringComparison.Ordinal)
        && call.ArgumentList.Arguments.Count is 3 or 4;

    private string Arguments(BaseArgumentListSyntax list) => string.Join(", ", list.Arguments.Select(a => Argument(a.Expression)));

    // A method of the class passed as an argument (a method group: LazyEntry(__Create_1, true)) becomes a delegate of `object M()`.
    private string Argument(ExpressionSyntax expression) =>
        expression is IdentifierNameSyntax identifier && _methods.Contains(identifier.Identifier.Text)
            ? $"System.Func<obj>(this.{Name(identifier.Identifier.Text)})"
            : Expression(expression);

    private static string Literal(LiteralExpressionSyntax literal)
    {
        switch (literal.Kind())
        {
            case SyntaxKind.NullLiteralExpression:
            case SyntaxKind.DefaultLiteralExpression:
                return "null";
            case SyntaxKind.TrueLiteralExpression:
                return "true";
            case SyntaxKind.FalseLiteralExpression:
                return "false";
            case SyntaxKind.StringLiteralExpression:
                return "\"" + ((string)literal.Token.Value!).Replace("\\", "\\\\").Replace("\"", "\\\"").Replace("\r", "\\r").Replace("\n", "\\n").Replace("\t", "\\t") + "\"";
            case SyntaxKind.CharacterLiteralExpression:
                return "'" + ((char)literal.Token.Value!).ToString().Replace("\\", "\\\\").Replace("'", "\\'") + "'";
            case SyntaxKind.NumericLiteralExpression:
                return literal.Token.Value switch
                {
                    double d => NumberText(d.ToString("R", CultureInfo.InvariantCulture)),
                    float f => NumberText(f.ToString("R", CultureInfo.InvariantCulture)) + "f",
                    long l => l.ToString(CultureInfo.InvariantCulture) + "L",
                    int i => i.ToString(CultureInfo.InvariantCulture),
                    decimal m => m.ToString(CultureInfo.InvariantCulture) + "M",
                    uint u => u.ToString(CultureInfo.InvariantCulture) + "u",
                    _ => throw new NotSupportedException($"the number {literal.Token.Text}"),
                };
            default:
                throw new NotSupportedException($"the literal {literal.Kind()}");
        }
    }

    private static string NumberText(string text) => text switch
    {
        "NaN" => "nan",
        "Infinity" => "infinity",
        "-Infinity" => "-infinity",
        _ => text.IndexOfAny(new[] { '.', 'E' }) >= 0 ? text : text + ".0",
    };

    private static string Name(string name) => s_keywords.Contains(name) || name.StartsWith("@", StringComparison.Ordinal) ? "``" + name.TrimStart('@') + "``" : name;

    private string GenericArguments(SimpleNameSyntax name) =>
        name is GenericNameSyntax generic ? "<" + string.Join(", ", generic.TypeArgumentList.Arguments.Select(Type)) + ">" : string.Empty;

    private string Type(ExpressionSyntax type)
    {
        switch (type)
        {
            case PredefinedTypeSyntax predefined:
                return predefined.Keyword.Kind() switch
                {
                    SyntaxKind.ObjectKeyword => "obj",
                    SyntaxKind.StringKeyword => "string",
                    SyntaxKind.BoolKeyword => "bool",
                    SyntaxKind.IntKeyword => "int",
                    SyntaxKind.LongKeyword => "int64",
                    SyntaxKind.DoubleKeyword => "float",
                    SyntaxKind.FloatKeyword => "float32",
                    SyntaxKind.ByteKeyword => "byte",
                    SyntaxKind.CharKeyword => "char",
                    SyntaxKind.DecimalKeyword => "decimal",
                    _ => throw new NotSupportedException(predefined.Keyword.Text),
                };
            case NullableTypeSyntax nullable:
                return Type(nullable.ElementType);
            case AliasQualifiedNameSyntax alias:
                return "global." + Type(alias.Name);
            case QualifiedNameSyntax qualified:
                return Type(qualified.Left) + "." + Type(qualified.Right);
            case GenericNameSyntax { Identifier.Text: "__XsgCompiledProperty" } compiled:
                return "LibreWPF.Xaml.Generated.XsgCompiledProperty" + GenericArguments(compiled);
            case GenericNameSyntax generic:
                return Name(generic.Identifier.Text) + GenericArguments(generic);
            case IdentifierNameSyntax identifier:
                return Name(identifier.Identifier.Text);
            default:
                throw new NotSupportedException($"the type {type.Kind()} ({Short(type)}) has no F# form");
        }
    }

    private static string Short(SyntaxNode node)
    {
        var text = node.ToString().Replace("\r", " ").Replace("\n", " ");
        return text.Length > 70 ? text[..70] + "..." : text;
    }
}
